from taf.gnb.oam.coam.vdu.schemas.base.schema_common import SchemaField, SchemaObject


class BeamDataRfPortInfo(SchemaObject):
    polarization_mode = SchemaField(name='polarizationMode', not_null=True)
    index = SchemaField(name='index', not_null=True)
    identity = SchemaField(name='identity', not_null=True)

    def __init__(self, polarization_mode, index, identity):
        self.polarization_mode = polarization_mode
        self.index = index
        self.identity = identity

        super(BeamDataRfPortInfo, self).__init__()


class BeamData(SchemaObject):
    horizontal_beamwidth = SchemaField(name='horizontalBeamwidth', many=True)
    rf_port_info = SchemaField(name='rfPortInfo', klass=BeamDataRfPortInfo, many=True)
    vertical_beamwidth = SchemaField(name='verticalBeamwidth', many=True)

    def __init__(self, horizontal_beamwidth, rf_port_info, vertical_beamwidth):
        self.horizontal_beamwidth = horizontal_beamwidth
        self.rf_port_info = rf_port_info
        self.vertical_beamwidth = vertical_beamwidth

        super(BeamData, self).__init__()


class DetailedStatus(SchemaObject):
    id = SchemaField(name='id', not_null=True)
    status = SchemaField(name='status', not_null=True)
    error_text = SchemaField(name='errorText')

    def __init__(self, id, status, error_text):
        self.id = id
        self.status = status
        self.error_text = error_text

        super(DetailedStatus, self).__init__()


class ErrorCode(SchemaObject):
    code = SchemaField(name='code', optional=True)
    description = SchemaField(name='description', optional=True)

    def __init__(self, code, description):
        self.code = code
        self.description = description

        super(ErrorCode, self).__init__()


class Operation(SchemaObject):
    id = SchemaField(name='id', not_null=True)
    status = SchemaField(name='status', not_null=True)
    detailed_statuses = SchemaField(name='detailedStatuses', optional=True, many=True, klass=DetailedStatus)
    error_message = SchemaField(name='errorMessage', optional=True)
    error_code = SchemaField(name='errorCode', optional=True, klass=ErrorCode)

    def __init__(self, id, status, detailed_statuses, error_message, error_code):
        self.id = id
        self.status = status
        self.detailed_statuses = detailed_statuses
        self.error_message = error_message
        self.error_code = error_code

        super(Operation, self).__init__()


class GetBeamDataResponse(Operation):
    beam_data = SchemaField(name='beamData', optional=True, klass=BeamData)

    def __init__(self, id, status, detailed_statuses, error_message, error_code, beam_data):
        self.id = id
        self.status = status
        self.detailed_statuses = detailed_statuses
        self.error_message = error_message
        self.error_code = error_code
        self.beam_data = beam_data

        super(GetBeamDataResponse, self).__init__(id, status, detailed_statuses, error_message, error_code)
